// =========================================================
// FILTRAR CANDIDATOS PARA CONTROL POSTGRESQL - CAT
// =========================================================
//
// PostgreSQL es la autoridad para decidir posteriormente:
//
// - CREATED
// - ALREADY_PROCESSING
// - ALREADY_COMPLETED
// - ALREADY_ERROR
// - ALREADY_CANCELLED
//
// Este nodo solamente:
// 1. valida candidatos;
// 2. excluye archivos historicos anteriores al corte productivo
  //    (22/09/2026); PostgreSQL controla el procesamiento a partir
  //    de esa fecha;
// 3. ordena los candidatos.
//
// NO consulta el estado legado en JSON de contadores/archivos.
// NO controla reintentos.
// NO decide si un archivo ya fue procesado.
// =========================================================

const FECHA_CORTE_PG =
  new Date("2026-09-22T00:00:00-06:00");

// =========================================================
// FUNCIONES
// =========================================================

function cleanText(value) {
  return String(value ?? "").trim();
}

function obtenerFechaArchivo(archivo) {
  const valores = [
    archivo.last_write_time_utc,
    archivo.last_write_time
  ];

  for (const valor of valores) {
    const texto = cleanText(valor);

    if (!texto) {
      continue;
    }

    const fecha = new Date(texto);

    if (!Number.isNaN(fecha.getTime())) {
      return fecha;
    }
  }

  // Fallback si solamente existe YYYY-MM-DD.
  const fechaIso = cleanText(
    archivo.fecha_archivo_iso
  );

  if (fechaIso) {
    const fecha = new Date(
      `${fechaIso}T00:00:00-06:00`
    );

    if (!Number.isNaN(fecha.getTime())) {
      return fecha;
    }
  }

  return null;
}

function esCandidatoValido(archivo) {
  if (
    archivo.tipo_resultado !==
    "ARCHIVO_DETECTADO"
  ) {
    return false;
  }

  if (
    archivo.procesar_automaticamente !== true
  ) {
    return false;
  }

  if (!cleanText(archivo.file_path)) {
    return false;
  }

  if (!cleanText(archivo.file_name)) {
    return false;
  }

  return true;
}

// =========================================================
// FILTRAR
// =========================================================

const candidatos = $input
  .all()
  .map(item => item.json)

  .filter(esCandidatoValido)

  .map(archivo => {
    const fechaArchivo =
      obtenerFechaArchivo(archivo);

    return {
      archivo,
      fechaArchivo
    };
  })

  .filter(({ fechaArchivo }) => {

    // Si no podemos determinar una fecha confiable,
    // no se procesa automaticamente.
    if (!fechaArchivo) {
      return false;
    }

    // Archivos anteriores al 22/09/2026 son historicos/legacy.
    // A partir del 22/09/2026, PostgreSQL controla el
    // procesamiento (PROD).
    return fechaArchivo >= FECHA_CORTE_PG;
  });

// =========================================================
// ORDENAR
// =========================================================
//
// Procesamos primero los candidatos mas antiguos dentro
// del universo posterior al corte.
//
// Esto evita que un archivo pendiente pueda quedarse
// permanentemente detras de archivos mas recientes.
// =========================================================

candidatos.sort((a, b) => {
  return (
    a.fechaArchivo.getTime() -
    b.fechaArchivo.getTime()
  );
});

// =========================================================
// SALIDA
// =========================================================

return candidatos.map(
  ({ archivo, fechaArchivo }) => ({
    json: {
      ...archivo,

      control_procesado: "POSTGRESQL",

      fecha_corte_pg:
        FECHA_CORTE_PG.toISOString(),

      fecha_archivo_control:
        fechaArchivo.toISOString()
    }
  })
);

const path = require("path");

// =========================================================
// NORMALIZAR DATOS CAT
// Compatible con:
// - CAT normal: 1 remisión por artículo
// - CAT Torreón: 1 remisión por OC, con varios artículos
// =========================================================

const MODO_ESTRICTO_CATALOGO = true;
const MODO_ESTRICTO_TORREON_FINANZAS = false;
const IVA_TORREON = 0.16;

// =========================================================
// FUNCIONES GENERALES
// =========================================================

function cleanText(value) {
  return String(value ?? "").trim();
}

function cleanMultiline(value) {
  return cleanText(value)
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n[ \t]+/g, "\n")
    .trim();
}

function normalizeText(value) {
  return cleanText(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeCompact(value) {
  return normalizeText(value).replace(/[^A-Z0-9]/g, "");
}

function normalizeCode(value) {
  return cleanText(value)
    .toUpperCase()
    .replace(/\s+/g, "")
    .trim();
}

function normalizeTipoEmpaque(value) {
  return normalizeText(value)
    .replace(/\s+POR\s+/g, "_")
    .replace(/[\/\-\s]+/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "");
}

function getFirstExisting(...values) {
  for (const value of values) {
    const text = cleanText(value);

    if (text !== "") {
      return value;
    }
  }

  return "";
}

function rowToArray(json) {
  if (Array.isArray(json)) return json;
  if (Array.isArray(json.row)) return json.row;
  if (Array.isArray(json.data)) return json.data;

  const keys = Object.keys(json);

  const numericKeys = keys
    .filter(key => /^\d+$/.test(key))
    .sort((a, b) => Number(a) - Number(b));

  if (numericKeys.length > 0) {
    return numericKeys.map(key => json[key]);
  }

  const emptyKeys = keys
    .filter(key => key === "__EMPTY" || /^__EMPTY_\d+$/.test(key))
    .sort((a, b) => {
      const getIndex = key => {
        if (key === "__EMPTY") return 0;
        return Number(key.replace("__EMPTY_", ""));
      };

      return getIndex(a) - getIndex(b);
    });

  if (emptyKeys.length > 0) {
    return emptyKeys.map(key => json[key]);
  }

  return Object.values(json);
}

function makeKey(...parts) {
  return parts.map(part => normalizeText(part)).join("|");
}

function makeKeyRaw(...parts) {
  return parts.map(part => cleanText(part)).join("|");
}

function makeProductKey(clienteGrupo, plantaCodigo, subplantaCodigo, codigoExcel) {
  return makeKey(clienteGrupo, plantaCodigo, subplantaCodigo, codigoExcel);
}

function makeProductKeyRaw(clienteGrupo, plantaCodigo, subplantaCodigo, codigoExcel) {
  return makeKeyRaw(clienteGrupo, plantaCodigo, subplantaCodigo, codigoExcel);
}

function isNo(value) {
  const text = normalizeText(value);
  return text === "NO" || text === "N";
}

function esEtiquetaNoProducto(codigo, descripcion, row = []) {
  const textoCodigo = normalizeCompact(codigo);
  const textoDescripcion = normalizeCompact(descripcion);
  const textoBase = normalizeCompact(`${codigo} ${descripcion}`);
  const textoFila = normalizeCompact(Array.isArray(row) ? row.join(" ") : "");

  if (!textoFila) return true;

  const etiquetasCompactas = [
    "CODIGO",
    "DESCRIPCION",
    "TOTAL",
    "SUBTOTAL",
    "CONSOLIDAR",
    "FECHADEENTREGA",
    "TRANSPORTE",
    "SOLICITADOPOR",
    "VALORDEVENTA",
    "VALORFACTURA",
    "METODODEPAGO",
    "FORMADEPAGO",
    "LUGARDEEXPEDICION",
    "IMPORTECONLETRA",
    "MONEDA",
    "TIPODECAMBIO",
    "TASADECONVERSION",
    "TC",
    "OBSERVACIONES",
    "NOTAS"
  ];

  const textosARevisar = [
    textoCodigo,
    textoDescripcion,
    textoBase,
    textoFila
  ];

  return textosARevisar.some(texto =>
    etiquetasCompactas.some(etiqueta =>
      texto === etiqueta ||
      texto.startsWith(etiqueta)
    )
  );
}

// =========================================================
// FECHAS Y NÚMEROS
// =========================================================

function excelDateToString(value) {
  if (value === undefined || value === null) return "";

  if (value instanceof Date && !isNaN(value.getTime())) {
    const dd = String(value.getDate()).padStart(2, "0");
    const mm = String(value.getMonth() + 1).padStart(2, "0");
    const yyyy = value.getFullYear();

    return `${dd}/${mm}/${yyyy}`;
  }

  const text = cleanText(value);

  if (text === "") return "";
  if (text === "0") return "";

  const numberValue = Number(text);

  if (!isNaN(numberValue) && numberValue > 20000 && numberValue < 70000) {
    const excelEpoch = new Date(Date.UTC(1899, 11, 30));
    const date = new Date(excelEpoch.getTime() + numberValue * 86400000);

    const dd = String(date.getUTCDate()).padStart(2, "0");
    const mm = String(date.getUTCMonth() + 1).padStart(2, "0");
    const yyyy = date.getUTCFullYear();

    return `${dd}/${mm}/${yyyy}`;
  }

  return text;
}

function todayDdMmYyyyDash() {
  const now = new Date();

  const dd = String(now.getDate()).padStart(2, "0");
  const mm = String(now.getMonth() + 1).padStart(2, "0");
  const yyyy = now.getFullYear();

  return `${dd}-${mm}-${yyyy}`;
}

function parseNumber(value) {
  if (value === undefined || value === null) return null;

  let text = cleanText(value);

  if (text === "") return null;
  if (text === "-") return null;

  text = text
    .replace(/\$/g, "")
    .replace(/USD/gi, "")
    .replace(/MXN/gi, "")
    .replace(/\s+/g, "")
    .replace(/,/g, "");

  const numberValue = Number(text);

  if (isNaN(numberValue)) return null;

  return numberValue;
}

function buscarValorPorEtiqueta(rows, etiquetas) {
  const etiquetasNorm = etiquetas.map(etiqueta => normalizeCompact(etiqueta));

  for (let rowIndex = 0; rowIndex < rows.length; rowIndex++) {
    const row = rows[rowIndex];

    for (let col = 0; col < row.length; col++) {
      const cellRaw = cleanText(row[col]);
      const cellNorm = normalizeCompact(cellRaw);

      if (!cellNorm) continue;

      for (const etiqueta of etiquetasNorm) {
        if (cellNorm === etiqueta || cellNorm.startsWith(etiqueta)) {
          const despuesDeDosPuntos = cellRaw.split(":").slice(1).join(":").trim();

          if (despuesDeDosPuntos && parseNumber(despuesDeDosPuntos) !== null) {
            return despuesDeDosPuntos;
          }

          for (let offset = 1; offset <= 4; offset++) {
            const posibleValorDerecha = cleanText(row[col + offset]);

            if (posibleValorDerecha && parseNumber(posibleValorDerecha) !== null) {
              return posibleValorDerecha;
            }
          }

          for (let rowOffset = 1; rowOffset <= 4; rowOffset++) {
            const rowAbajo = rows[rowIndex + rowOffset];

            if (!rowAbajo) continue;

            const posibleValorAbajo = cleanText(rowAbajo[col]);

            if (posibleValorAbajo && parseNumber(posibleValorAbajo) !== null) {
              return posibleValorAbajo;
            }

            for (let colOffset = 1; colOffset <= 3; colOffset++) {
              const posibleValorDiagonal = cleanText(rowAbajo[col + colOffset]);

              if (posibleValorDiagonal && parseNumber(posibleValorDiagonal) !== null) {
                return posibleValorDiagonal;
              }
            }
          }
        }
      }
    }
  }

  return "";
}

function hasCantidad(value) {
  const numberValue = parseNumber(value);

  if (numberValue === null) return false;
  if (numberValue <= 0) return false;

  return true;
}

function parseCantidad(value) {
  const numberValue = parseNumber(value);

  if (numberValue === null || numberValue <= 0) {
    return null;
  }

  return numberValue;
}

function formatQuantity(value) {
  const numberValue = Number(value);

  if (isNaN(numberValue)) return "";

  if (Number.isInteger(numberValue)) {
    return String(numberValue);
  }

  return String(numberValue).replace(/\.?0+$/, "");
}

function formatQuantityTorreon(value) {
  const numberValue = Number(value);

  if (isNaN(numberValue)) return "";

  return numberValue.toLocaleString("en-US", {
    minimumFractionDigits: 4,
    maximumFractionDigits: 4
  });
}

function formatNumber(value, decimals = 2) {
  if (value === undefined || value === null || isNaN(Number(value))) return "";

  return Number(value).toLocaleString("en-US", {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals
  });
}

function formatCurrency(value, decimals = 2) {
  if (value === undefined || value === null || isNaN(Number(value))) return "";

  return `$${formatNumber(value, decimals)}`;
}

function formatTipoCambio(value) {
  const numberValue = parseNumber(value);

  if (numberValue === null) return "";

  return `$${numberValue.toLocaleString("en-US", {
    minimumFractionDigits: 4,
    maximumFractionDigits: 4
  })}`;
}

// =========================================================
// UNIDADES / EMPAQUE
// =========================================================

function canonicalUnidadRemision(value) {
  const key = normalizeText(value);

  const map = {
    BOLSA: "BOLSAS",
    BOLSAS: "BOLSAS",

    HOJA: "HOJAS",
    HOJAS: "HOJAS",

    ROLLO: "ROLLOS",
    ROLLOS: "ROLLOS",

    PAQUETE: "PAQUETES",
    PAQUETES: "PAQUETES",

    PIEZA: "PIEZAS",
    PIEZAS: "PIEZAS",

    UNIDAD: "PIEZAS",
    UNIDADES: "PIEZAS"
  };

  return map[key] || key;
}

function getUnidadLabel(unidadRemision) {
  const key = canonicalUnidadRemision(unidadRemision);

  const map = {
    BOLSAS: "bolsas",
    HOJAS: "hojas",
    ROLLOS: "rollos",
    PAQUETES: "paquetes",
    PIEZAS: "piezas"
  };

  return map[key] || cleanText(unidadRemision).toLowerCase();
}

function getTipoEmpaqueInfo(tipoEmpaque) {
  const key = normalizeTipoEmpaque(tipoEmpaque);

  const map = {
    BOLSAS_ROLLO: {
      leyenda: "bolsas por rollo",
      tipo: "rollo",
      encabezado: "Cantidad por rollo"
    },
    BOLSAS_PAQUETE: {
      leyenda: "bolsas por paquete",
      tipo: "paquete",
      encabezado: "Cantidad por paquete"
    },
    BOLSAS_CAJA: {
      leyenda: "bolsas por caja",
      tipo: "caja",
      encabezado: "Cantidad por caja"
    },
    HOJAS_ROLLO: {
      leyenda: "hojas por rollo",
      tipo: "rollo",
      encabezado: "Cantidad por rollo"
    },
    HOJAS_PAQUETE: {
      leyenda: "hojas por paquete",
      tipo: "paquete",
      encabezado: "Cantidad por paquete"
    },
    PIEZAS_CAJA: {
      leyenda: "piezas por caja",
      tipo: "caja",
      encabezado: "Cantidad por caja"
    },
    PIEZAS_PAQUETE: {
      leyenda: "piezas por paquete",
      tipo: "paquete",
      encabezado: "Cantidad por paquete"
    },
    ROLLOS_CAJA: {
      leyenda: "rollos por caja",
      tipo: "caja",
      encabezado: "Cantidad por caja"
    },
    PAQUETES_CAJA: {
      leyenda: "paquetes por caja",
      tipo: "caja",
      encabezado: "Cantidad por caja"
    },
    NA: {
      leyenda: "",
      tipo: "empaque",
      encabezado: "Cantidad por empaque"
    },
    N_A: {
      leyenda: "",
      tipo: "empaque",
      encabezado: "Cantidad por empaque"
    },
    SIN_EMPAQUE: {
      leyenda: "",
      tipo: "empaque",
      encabezado: "Cantidad por empaque"
    }
  };

  if (map[key]) return map[key];

  if (key.includes("_")) {
    const parts = key.split("_").filter(Boolean);

    if (parts.length >= 2) {
      const unidad = parts[0].toLowerCase();
      const tipoRaw = parts.slice(1).join("_").toLowerCase();

      const tipo = tipoRaw
        .replace(/s$/, "")
        .replace(/_/g, " ");

      return {
        leyenda: `${unidad} por ${tipo}`,
        tipo,
        encabezado: `Cantidad por ${tipo}`
      };
    }
  }

  return {
    leyenda: "",
    tipo: "empaque",
    encabezado: "Cantidad por empaque"
  };
}

function construirCantidadPorEmpaque(producto) {
  const cantidadPorEmpaque = cleanText(
    getFirstExisting(
      producto.cantidad_por_empaque,
      producto.cantidad_por_rollo,
      producto.cantidad_por_rollo_empaque,
      producto.cantidad_por_paquete,
      producto.qty_per_packaging_default
    )
  );

  const tipoEmpaqueRaw = cleanText(producto.tipo_empaque);
  const info = getTipoEmpaqueInfo(tipoEmpaqueRaw);

  if (!cantidadPorEmpaque || !info.leyenda) {
    return {
      cantidad_por_empaque_valor: cantidadPorEmpaque,
      tipo_empaque_codigo: normalizeTipoEmpaque(tipoEmpaqueRaw),
      tipo_empaque_label: info.tipo,
      encabezado_cantidad_por_empaque: info.encabezado,
      cantidad_por_empaque_texto: ""
    };
  }

  return {
    cantidad_por_empaque_valor: cantidadPorEmpaque,
    tipo_empaque_codigo: normalizeTipoEmpaque(tipoEmpaqueRaw),
    tipo_empaque_label: info.tipo,
    encabezado_cantidad_por_empaque: info.encabezado,
    cantidad_por_empaque_texto: `${cantidadPorEmpaque} ${info.leyenda}`
  };
}

// =========================================================
// IMPORTE EN LETRA SIMPLE PARA USD
// =========================================================

function unidades(n) {
  const map = [
    "",
    "UNO",
    "DOS",
    "TRES",
    "CUATRO",
    "CINCO",
    "SEIS",
    "SIETE",
    "OCHO",
    "NUEVE",
    "DIEZ",
    "ONCE",
    "DOCE",
    "TRECE",
    "CATORCE",
    "QUINCE",
    "DIECISÉIS",
    "DIECISIETE",
    "DIECIOCHO",
    "DIECINUEVE"
  ];

  return map[n] || "";
}

function decenas(n) {
  if (n < 20) return unidades(n);

  const d = Math.floor(n / 10);
  const u = n % 10;

  const map = {
    2: "VEINTE",
    3: "TREINTA",
    4: "CUARENTA",
    5: "CINCUENTA",
    6: "SESENTA",
    7: "SETENTA",
    8: "OCHENTA",
    9: "NOVENTA"
  };

  if (d === 2 && u > 0) {
    return `VEINTI${unidades(u).toLowerCase()}`.toUpperCase();
  }

  if (u === 0) return map[d];

  return `${map[d]} Y ${unidades(u)}`;
}

function centenas(n) {
  if (n < 100) return decenas(n);

  const c = Math.floor(n / 100);
  const r = n % 100;

  if (n === 100) return "CIEN";

  const map = {
    1: "CIENTO",
    2: "DOSCIENTOS",
    3: "TRESCIENTOS",
    4: "CUATROCIENTOS",
    5: "QUINIENTOS",
    6: "SEISCIENTOS",
    7: "SETECIENTOS",
    8: "OCHOCIENTOS",
    9: "NOVECIENTOS"
  };

  if (r === 0) return map[c];

  return `${map[c]} ${decenas(r)}`;
}

function enteroALetras(n) {
  n = Math.floor(Number(n));

  if (n === 0) return "CERO";
  if (n < 1000) return centenas(n);

  if (n < 1000000) {
    const miles = Math.floor(n / 1000);
    const resto = n % 1000;

    let textoMiles = "";

    if (miles === 1) {
      textoMiles = "MIL";
    } else {
      textoMiles = `${centenas(miles)} MIL`;
    }

    if (resto === 0) return textoMiles;

    return `${textoMiles} ${centenas(resto)}`;
  }

  const millones = Math.floor(n / 1000000);
  const resto = n % 1000000;

  let textoMillones = "";

  if (millones === 1) {
    textoMillones = "UN MILLÓN";
  } else {
    textoMillones = `${enteroALetras(millones)} MILLONES`;
  }

  if (resto === 0) return textoMillones;

  return `${textoMillones} ${enteroALetras(resto)}`;
}

function importeUsdALetras(value) {
  if (value === undefined || value === null || isNaN(Number(value))) return "";

  const total = Number(value);
  const entero = Math.floor(total);
  const centavos = Math.round((total - entero) * 100);
  const centavosText = String(centavos).padStart(2, "0");

  return `${enteroALetras(entero)} DÓLARES ${centavosText}/100 USD`;
}

// =========================================================
// VALIDACIONES DE PLANTILLA
// =========================================================

function getCell(rows, rowIndex, colIndex) {
  return cleanText(rows[rowIndex]?.[colIndex]);
}

function validarPlantillaBase(rows) {
  const checks = [
    {
      cell: "A7",
      row: 6,
      col: 0,
      expected: "CODIGO"
    },
    {
      cell: "D7",
      row: 6,
      col: 3,
      expected: "DESCRIPCION"
    },
    {
      cell: "I7",
      row: 6,
      col: 8,
      expected: "CANTIDAD BOLSAS/HOJAS"
    },
    {
      cell: "J7",
      row: 6,
      col: 9,
      expected: "CANTIDAD ROLLOS/PAQUETE"
    },
    {
      cell: "K7",
      row: 6,
      col: 10,
      expected: "OC CLIENTE"
    }
  ];

  const errores = [];

  for (const check of checks) {
    const actual = normalizeText(getCell(rows, check.row, check.col));
    const expected = normalizeText(check.expected);

    if (actual !== expected) {
      errores.push(
        `${check.cell}: se esperaba "${check.expected}" y se encontró "${getCell(rows, check.row, check.col)}".`
      );
    }
  }

  if (errores.length > 0) {
    throw new Error(
      "La plantilla no tiene la estructura esperada.\n\n" +
      errores.join("\n")
    );
  }
}

function validarVersionPlantilla(rows) {
  const version = cleanText(rows[3]?.[7]);

  if (version !== "CAT_REMISION_V1") {
    throw new Error(
      `La versión de plantilla no es válida. En H4 se esperaba "CAT_REMISION_V1" y se encontró "${version}".`
    );
  }
}

// =========================================================
// CATÁLOGOS
// =========================================================

function objectValuesSafe(value) {
  if (!value || typeof value !== "object") return [];
  if (Array.isArray(value)) return value;
  return Object.values(value);
}

function buscarEnMapa(mapa, keys) {
  if (!mapa || typeof mapa !== "object") return null;

  for (const key of keys) {
    if (mapa[key]) return mapa[key];
  }

  return null;
}

function buscarProducto(productosMap, contexto, codigoExcel) {
  const clienteGrupo = contexto.cliente_grupo;
  const plantaCodigo = contexto.planta_codigo;
  const subplantaCodigo = contexto.subplanta_codigo || "";

  const keys = [
    makeProductKey(clienteGrupo, plantaCodigo, subplantaCodigo, codigoExcel),
    makeProductKeyRaw(clienteGrupo, plantaCodigo, subplantaCodigo, codigoExcel),

    makeProductKey(clienteGrupo, plantaCodigo, "", codigoExcel),
    makeProductKeyRaw(clienteGrupo, plantaCodigo, "", codigoExcel)
  ];

  const exacto = buscarEnMapa(productosMap, keys);

  if (exacto) return exacto;

  const candidatos = objectValuesSafe(productosMap).filter(producto => {
    const mismoCliente =
      normalizeText(producto.cliente_grupo) === normalizeText(clienteGrupo);

    const mismaPlanta =
      normalizeText(producto.planta_codigo) === normalizeText(plantaCodigo);

    const mismoCodigo =
      normalizeCode(producto.codigo_excel) === normalizeCode(codigoExcel);

    const subProducto = normalizeText(producto.subplanta_codigo || "");
    const subContexto = normalizeText(subplantaCodigo || "");

    const mismaSubplanta =
      subContexto === "" ||
      subProducto === subContexto ||
      subProducto === "";

    return mismoCliente && mismaPlanta && mismoCodigo && mismaSubplanta;
  });

  if (candidatos.length === 1) return candidatos[0];

  if (candidatos.length > 1) {
    throw new Error(
      `Catálogo ambiguo para el código ${codigoExcel}. Hay más de un producto posible para ${clienteGrupo} / ${plantaCodigo} / ${subplantaCodigo}.`
    );
  }

  return null;
}

function buscarCliente(clientesMap, contexto) {
  const clienteGrupo = contexto.cliente_grupo;
  const plantaCodigo = contexto.planta_codigo;
  const subplantaCodigo = contexto.subplanta_codigo || "";

  const keys = [
    makeKey(clienteGrupo, plantaCodigo, subplantaCodigo),
    makeKeyRaw(clienteGrupo, plantaCodigo, subplantaCodigo),

    makeKey(clienteGrupo, plantaCodigo, ""),
    makeKeyRaw(clienteGrupo, plantaCodigo, "")
  ];

  const exacto = buscarEnMapa(clientesMap, keys);

  if (exacto) return exacto;

  const candidatos = objectValuesSafe(clientesMap).filter(cliente => {
    const mismoCliente =
      normalizeText(cliente.cliente_grupo) === normalizeText(clienteGrupo);

    const mismaPlanta =
      normalizeText(cliente.planta_codigo) === normalizeText(plantaCodigo);

    const subCliente = normalizeText(cliente.subplanta_codigo || "");
    const subContexto = normalizeText(subplantaCodigo || "");

    const mismaSubplanta =
      subContexto === "" ||
      subCliente === subContexto ||
      subCliente === "";

    return mismoCliente && mismaPlanta && mismaSubplanta;
  });

  if (candidatos.length === 1) return candidatos[0];

  if (candidatos.length > 1) {
    const conSubplanta = candidatos.find(cliente =>
      normalizeText(cliente.subplanta_codigo || "") === normalizeText(subplantaCodigo || "")
    );

    if (conSubplanta) return conSubplanta;
  }

  return null;
}

// =========================================================
// PRECIOS / TORREÓN
// =========================================================

function getPrecioUnitario(row, producto) {
  const desdeCatalogo = getFirstExisting(
    producto.precio_unitario_usd,
    producto.precio_unitario,
    producto.precio_usd,
    producto.precio
  );

  const precioCatalogo = parseNumber(desdeCatalogo);

  if (precioCatalogo !== null) {
    return precioCatalogo;
  }

  const posiblesValores = [];

  for (let col = 11; col <= 17; col++) {
    const numero = parseNumber(row[col]);

    if (numero !== null && numero > 0) {
      posiblesValores.push(numero);
    }
  }

  if (posiblesValores.length === 0) {
    return null;
  }

  return posiblesValores[0];
}

function calcularImporteTorreon(cantidad, precioUnitario) {
  if (cantidad === null || precioUnitario === null) {
    return null;
  }

  return Number(cantidad) * Number(precioUnitario);
}

function agruparTorreonPorOC(items) {
  const grupos = new Map();

  for (const item of items) {
    const data = item.json;
    const oc = cleanText(data.orden_compra || "SIN_OC");

    if (!grupos.has(oc)) {
      grupos.set(oc, []);
    }

    grupos.get(oc).push(data);
  }

  const salidaAgrupada = [];
  let index = 0;

  for (const [oc, articulosGrupo] of grupos.entries()) {
    index += 1;

    const base = articulosGrupo[0];

    let subtotalRaw = 0;

    const articulos = articulosGrupo.map(articulo => {
      const importeRaw = parseNumber(articulo.importe);

      if (importeRaw !== null) {
        subtotalRaw += importeRaw;
      }

      return {
        codigo: articulo.codigo,
        cantidad_torreon: articulo.cantidad_torreon,
        unidad_torreon: articulo.unidad_torreon,
        descripcion: articulo.descripcion,
        iva_linea: articulo.iva_linea || "002 IVA | Tipo Factor: Tasa | Tasa: 0.1600",
        precio_unitario: articulo.precio_unitario,
        importe: articulo.importe
      };
    });

    const ivaRaw = subtotalRaw * IVA_TORREON;
    const totalRaw = subtotalRaw + ivaRaw;

    salidaAgrupada.push({
      json: {
        ...base,

        articulo_index: index,

        codigo: `OC_${oc}`,
        numero_parte: `OC_${oc}`,

        orden_compra: oc,

        es_remision_torreon_agrupada: true,
        total_articulos_torreon: articulos.length,
        articulos,

        subtotal: formatCurrency(subtotalRaw, 2),
        descuento: "$0.00",
        iva: formatCurrency(ivaRaw, 2),
        total: formatCurrency(totalRaw, 2),
        importe_letra: importeUsdALetras(totalRaw)
      }
    });
  }

  return salidaAgrupada;
}

// =========================================================
// ENTRADAS DESDE N8N
// =========================================================

// Propagar ejecución PG ya conserva el contexto original de
// Preparar archivo CAT e incorpora documento_origen_id y ejecucion_id.
const contexto = $("Propagar ejecución PG").first().json;

if (!contexto.documento_origen_id || !contexto.ejecucion_id) {
  throw new Error(
    "Normalizar datos CAT no recibió documento_origen_id o ejecucion_id desde PostgreSQL."
  );
}

const catalogo = $("Preparar catálogo CAT").first().json;

const archivoActual =
  contexto.file_name ||
  contexto.source_base_name ||
  "archivo no identificado";

const productosMap =
  catalogo.productos_map ||
  catalogo.productosMap ||
  catalogo.productos ||
  {};

const clientesMap =
  catalogo.clientes_map ||
  catalogo.clientesMap ||
  catalogo.clientes ||
  {};

const rows = $input.all().map(item => rowToArray(item.json));

if (rows.length === 0) {
  throw new Error("No se recibieron filas del Excel en Normalizar datos CAT.");
}

try {
  validarPlantillaBase(rows);
  validarVersionPlantilla(rows);
} catch (error) {
  throw new Error(`Error en archivo: ${archivoActual}\n\n${error.message}`);
}

// =========================================================
// CONSTANTES DE LECTURA DE EXCEL
// =========================================================

const FECHA_ENTREGA_ROW = 3; // F4
const FECHA_ENTREGA_COL = 5;

const START_ROW = 7; // Excel row 8

const COL_CODIGO = 0;       // A
const COL_DESCRIPCION = 3;  // D
const COL_CANTIDAD_BH = 8;  // I
const COL_CANTIDAD_RP = 9;  // J
const COL_OC_CLIENTE = 10;  // K

const fechaEntrega = excelDateToString(rows[FECHA_ENTREGA_ROW]?.[FECHA_ENTREGA_COL]);

if (!fechaEntrega) {
  throw new Error(
    `Error en archivo: ${archivoActual}\n\nLa fecha de entrega oficial no está capturada en F4.`
  );
}

const clienteCatalogo = buscarCliente(clientesMap, contexto);

if (!clienteCatalogo && MODO_ESTRICTO_CATALOGO) {
  throw new Error(
    `Error en archivo: ${archivoActual}\n\nNo se encontró cliente/planta en catálogo para: ${contexto.cliente_grupo} | ${contexto.planta_codigo} | ${contexto.subplanta_codigo || ""}`
  );
}

const esTorreonContexto = contexto.cliente_grupo === "CAT_TORREON";

// =========================================================
// PROCESAMIENTO DE FILAS
// =========================================================

const salida = [];
const errores = [];

for (let rowIndex = START_ROW; rowIndex < rows.length; rowIndex++) {
  const row = rows[rowIndex];

  const descripcionExcel = cleanMultiline(row[COL_DESCRIPCION]);

  if (esEtiquetaNoProducto(row[COL_CODIGO], descripcionExcel, row)) {
    continue;
  }

  const codigo = normalizeCode(row[COL_CODIGO]);
  const cantidadBolsasHojas = row[COL_CANTIDAD_BH];
  const cantidadRollosPaquetes = row[COL_CANTIDAD_RP];
  const ordenCompra = cleanText(row[COL_OC_CLIENTE]);

  const excelRowNumber = rowIndex + 1;

  if (!codigo) {
    if (hasCantidad(cantidadBolsasHojas) || hasCantidad(cantidadRollosPaquetes)) {
      errores.push(
        `Fila ${excelRowNumber}: hay cantidad capturada, pero falta código.`
      );
    }

    continue;
  }

  const producto = buscarProducto(productosMap, contexto, codigo);

  if (!producto) {
    if (MODO_ESTRICTO_CATALOGO) {
      errores.push(
        `Fila ${excelRowNumber}, código ${codigo}: no existe en el catálogo para ${contexto.cliente_grupo} | ${contexto.planta_codigo} | ${contexto.subplanta_codigo || ""}.`
      );
    }

    continue;
  }

  if (isNo(producto.activo)) {
    errores.push(
      `Fila ${excelRowNumber}, código ${codigo}: el producto está marcado como activo = NO en el catálogo.`
    );

    continue;
  }

  const unidadRemisionOriginal = normalizeText(producto.unidad_remision);
  const unidadRemision = canonicalUnidadRemision(unidadRemisionOriginal);
  const unidadRemisionLabel = getUnidadLabel(unidadRemision);

  let cantidadBase = "";
  let columnaCantidadUsada = "";

  const tieneCantidadBolsasHojas = hasCantidad(cantidadBolsasHojas);
  const tieneCantidadRollosPaquetes = hasCantidad(cantidadRollosPaquetes);

  if (
    unidadRemision === "BOLSAS" ||
    unidadRemision === "HOJAS" ||
    unidadRemision === "PIEZAS"
  ) {
    cantidadBase = cantidadBolsasHojas;
    columnaCantidadUsada = "Cantidad bolsas/hojas";
  } else if (
    unidadRemision === "ROLLOS" ||
    unidadRemision === "PAQUETES"
  ) {
    cantidadBase = cantidadRollosPaquetes;
    columnaCantidadUsada = "Cantidad Rollos/paquete";
  } else {
    errores.push(
      `Fila ${excelRowNumber}, código ${codigo}: unidad_remision inválida en catálogo: "${producto.unidad_remision}". Debe ser BOLSA(S), HOJA(S), ROLLO(S), PAQUETE(S) o PIEZA(S).`
    );

    continue;
  }

  if (esTorreonContexto && !hasCantidad(cantidadBase)) {
    if (tieneCantidadBolsasHojas) {
      cantidadBase = cantidadBolsasHojas;
      columnaCantidadUsada = "Cantidad bolsas/hojas";
    } else if (tieneCantidadRollosPaquetes) {
      cantidadBase = cantidadRollosPaquetes;
      columnaCantidadUsada = "Cantidad Rollos/paquete";
    }
  }

  if (!hasCantidad(cantidadBase)) {
    continue;
  }

  if (!ordenCompra) {
    errores.push(
      `Fila ${excelRowNumber}, código ${codigo}: falta OC cliente.`
    );

    continue;
  }

  const cantidadNumerica = parseCantidad(cantidadBase);

  if (!cantidadNumerica) {
    errores.push(
      `Fila ${excelRowNumber}, código ${codigo}: falta cantidad válida en "${columnaCantidadUsada}".`
    );

    continue;
  }

  const descripcionCatalogo = getFirstExisting(
    producto.descripcion_catalogo,
    producto.descripcion,
    producto.descripcion_producto
  );

  const descripcionFinal = cleanMultiline(
    getFirstExisting(
      descripcionCatalogo,
      descripcionExcel
    )
  );

  const numeroParte = cleanText(
    getFirstExisting(
      producto.numero_parte,
      producto.part_number,
      producto.no_parte
    )
  );

  const empaqueInfo = construirCantidadPorEmpaque(producto);

  const cantidadEntregar =
    `${formatQuantity(cantidadNumerica)} ${unidadRemisionLabel}`;

  const cantidadPorEmpaqueTexto = empaqueInfo.cantidad_por_empaque_texto;

  const clienteRemision = cleanText(
    getFirstExisting(
      clienteCatalogo?.cliente_remision,
      clienteCatalogo?.nombre_cliente,
      clienteCatalogo?.cliente,
      clienteCatalogo?.razon_social,
      contexto.cliente_grupo
    )
  );

  const razonSocial = cleanText(
    getFirstExisting(
      clienteCatalogo?.razon_social,
      clienteCatalogo?.cliente,
      ""
    )
  );

  const rfc = cleanText(
    getFirstExisting(
      clienteCatalogo?.rfc,
      clienteCatalogo?.RFC,
      ""
    )
  );

  const domicilio = cleanMultiline(
    getFirstExisting(
      clienteCatalogo?.domicilio,
      clienteCatalogo?.direccion,
      clienteCatalogo?.dirección,
      ""
    )
  );

  const telefono = cleanText(
    getFirstExisting(
      clienteCatalogo?.telefono_default,
      clienteCatalogo?.telefono,
      clienteCatalogo?.tel,
      ""
    )
  );

  const atencion = cleanText(
    getFirstExisting(
      clienteCatalogo?.atencion_default,
      clienteCatalogo?.atencion,
      clienteCatalogo?.atención,
      ""
    )
  );

  const numeroProveedor = cleanText(
    getFirstExisting(
      clienteCatalogo?.numero_proveedor,
      clienteCatalogo?.proveedor,
      "D8599K0"
    )
  );

  let camposTorreon = {};

  if (esTorreonContexto) {
    const precioUnitario = getPrecioUnitario(row, producto);
    const importe = calcularImporteTorreon(cantidadNumerica, precioUnitario);

    const subtotal = importe;
    const iva = subtotal !== null ? subtotal * IVA_TORREON : null;
    const total = subtotal !== null ? subtotal + iva : null;

    const tipoCambioExcel = buscarValorPorEtiqueta(rows, [
      "T.C.",
      "TC",
      "T C",
      "TIPO DE CAMBIO",
      "TIPO CAMBIO",
      "TASA DE CONVERSION",
      "TASA DE CONVERSIÓN"
    ]);

    const tipoCambioRaw = cleanText(
      getFirstExisting(
        tipoCambioExcel,
        clienteCatalogo?.tipo_cambio_default,
        clienteCatalogo?.tipo_cambio,
        producto.tipo_cambio_default,
        producto.tipo_cambio,
        ""
      )
    );

    const tipoCambio = formatTipoCambio(tipoCambioRaw);

    const pendientesTorreon = [];

    if (precioUnitario === null) {
      pendientesTorreon.push("precio_unitario");
    }

    if (importe === null) {
      pendientesTorreon.push("importe/subtotal");
    }

    if (total === null) {
      pendientesTorreon.push("total");
    }

    if (pendientesTorreon.length > 0 && MODO_ESTRICTO_TORREON_FINANZAS) {
      errores.push(
        `Fila ${excelRowNumber}, código ${codigo}: faltan datos financieros para Torreón: ${pendientesTorreon.join(", ")}.`
      );

      continue;
    }

    camposTorreon = {
      fecha_creacion: todayDdMmYyyyDash(),

      almacen: cleanText(
        getFirstExisting(
          clienteCatalogo?.almacen,
          clienteCatalogo?.almacén,
          "DCMX Almacén Principal"
        )
      ),

      metodo_pago: cleanText(
        getFirstExisting(
          clienteCatalogo?.metodo_pago,
          clienteCatalogo?.método_pago,
          "Por Definir"
        )
      ),

      forma_pago: cleanText(
        getFirstExisting(
          clienteCatalogo?.forma_pago,
          "PPD"
        )
      ),

      lugar_expedicion: cleanText(
        getFirstExisting(
          clienteCatalogo?.lugar_expedicion,
          clienteCatalogo?.lugar_expedición,
          "Aguascalientes, Aguascalientes"
        )
      ),

      moneda: cleanText(
        getFirstExisting(
          clienteCatalogo?.moneda,
          producto.moneda,
          "USD"
        )
      ),

      tipo_cambio: tipoCambio,

      cantidad_torreon: formatQuantityTorreon(cantidadNumerica),

      unidad_torreon: cleanText(
        getFirstExisting(
          producto.unidad_torreon,
          producto.unidad_cfdi,
          producto.unidad_sat,
          "PIEZA"
        )
      ),

      iva_linea: "002 IVA | Tipo Factor: Tasa | Tasa: 0.1600",

      precio_unitario: precioUnitario !== null ? formatNumber(precioUnitario, 4) : "",
      importe: importe !== null ? formatNumber(importe, 4) : "",

      subtotal: subtotal !== null ? formatCurrency(subtotal, 2) : "",
      descuento: "$0.00",
      iva: iva !== null ? formatCurrency(iva, 2) : "",
      total: total !== null ? formatCurrency(total, 2) : "",

      importe_letra: total !== null ? importeUsdALetras(total) : "",

      torreon_pendiente_finanzas: pendientesTorreon.length > 0,
      torreon_campos_pendientes: pendientesTorreon.join(", ")
    };
  }

  salida.push({
    json: {
      ...contexto,

      output_dir: contexto.carpeta_salida_pruebas || contexto.output_dir,
      temp_dir: contexto.temp_dir,
      templates_dir: contexto.templates_dir,
      scripts_dir: contexto.scripts_dir,
      copy_dir: contexto.copy_dir,

      pdf_script_path:
        contexto.pdf_script_path ||
        path.join(contexto.scripts_dir || "", "html-to-pdf-cat.ps1"),

      clean_script_path:
        contexto.clean_script_path ||
        path.join(contexto.scripts_dir || "", "limpiar-html-temporal-cat.ps1"),

      articulo_index: salida.length + 1,
      excel_row_number: excelRowNumber,

      fecha: fechaEntrega,
      fecha_entrega: fechaEntrega,

      orden_compra: ordenCompra,
      numero_proveedor: numeroProveedor,

      cliente: clienteRemision,
      razon_social: razonSocial,
      rfc,
      domicilio,
      telefono,
      atencion,

      codigo,
      descripcion: descripcionFinal,
      numero_parte: numeroParte,

      cantidad_entregar: cantidadEntregar,

      cantidad_por_rollo: cantidadPorEmpaqueTexto,

      cantidad_por_empaque: cantidadPorEmpaqueTexto,
      cantidad_por_empaque_texto: cantidadPorEmpaqueTexto,
      cantidad_por_empaque_valor: empaqueInfo.cantidad_por_empaque_valor,
      tipo_empaque_codigo: empaqueInfo.tipo_empaque_codigo,
      tipo_empaque_label: empaqueInfo.tipo_empaque_label,
      encabezado_cantidad_por_empaque: empaqueInfo.encabezado_cantidad_por_empaque,

      unidad_remision: unidadRemision,
      unidad_remision_original: unidadRemisionOriginal,
      unidad_remision_label: unidadRemisionLabel,
      cantidad_numerica: cantidadNumerica,
      columna_cantidad_usada: columnaCantidadUsada,

      producto_catalogo_encontrado: true,

      ...camposTorreon
    }
  });
}

if (errores.length > 0) {
  throw new Error(
    `Error en archivo: ${archivoActual}\n\n` +
    errores.join("\n")
  );
}

const salidaFinal =
  esTorreonContexto
    ? agruparTorreonPorOC(salida)
    : salida;

if (salidaFinal.length === 0) {
  throw new Error(
    `Error en archivo: ${archivoActual}\n\nNo se encontraron artículos válidos para generar remisión.`
  );
}

return salidaFinal;

const fs = require("fs");
const path = require("path");

function cleanText(value) {
  return String(value ?? "").trim();
}

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function escapeHtmlWithBreaks(value) {
  return escapeHtml(value).replace(/\r?\n/g, "<br>");
}

function toFileUri(windowsPath) {
  const normalized = cleanText(windowsPath).replace(/\\/g, "/");
  return encodeURI("file:///" + normalized.replace(/^\/+/, ""));
}

function renderTemplate(template, data) {
  let html = template;

  for (const [key, value] of Object.entries(data)) {
    const placeholder = `{{${key}}}`;

    if (key === "filas_articulos") {
      html = html.replaceAll(placeholder, String(value ?? ""));
      continue;
    }

    if (
      key === "domicilio" ||
      key === "direccion_entrega" ||
      key === "descripcion" ||
      key === "cantidad_por_rollo" ||
      key === "receptor_domicilio" ||
      key === "emisor_domicilio"
    ) {
      html = html.replaceAll(placeholder, escapeHtmlWithBreaks(value));
    } else {
      html = html.replaceAll(placeholder, escapeHtml(value));
    }
  }

  html = html.replace(/\{\{[^}]+\}\}/g, "");

  return html;
}

function todayDdMmYyyy() {
  const now = new Date();
  const dd = String(now.getDate()).padStart(2, "0");
  const mm = String(now.getMonth() + 1).padStart(2, "0");
  const yyyy = now.getFullYear();

  return `${dd}-${mm}-${yyyy}`;
}

const first = $input.first().json;

fs.mkdirSync(first.temp_dir, { recursive: true });

for (const file of fs.readdirSync(first.temp_dir)) {
  if (file.toLowerCase().endsWith(".html")) {
    fs.unlinkSync(path.join(first.temp_dir, file));
  }
}

const templateFileName =
  first.cliente_grupo === "CAT_TORREON"
    ? "REM-Plantilla-CAT-TORREON.html"
    : "REM-Plantilla-CAT.html";

const templatePath = path.join(
  first.templates_dir,
  templateFileName
);

if (!fs.existsSync(templatePath)) {
  throw new Error(`No existe el template CAT: ${templatePath}`);
}

let template = fs.readFileSync(templatePath, "utf8");

// Convertir rutas relativas del template a rutas absolutas
const fontTwCenUri = toFileUri(path.join(first.templates_dir, "fonts", "TwCenMT.ttf"));
const fontNamataUri = toFileUri(path.join(first.templates_dir, "fonts", "Namata-Semibold.otf"));

const bgUri = toFileUri(path.join(first.templates_dir, "images", "REM-Plantilla.svg"));
const logoDcUri = toFileUri(path.join(first.templates_dir, "images", "DC_logo.jpg"));

template = template
  .replaceAll('url("./fonts/TwCenMT.ttf")', `url("${fontTwCenUri}")`)
  .replaceAll("url('./fonts/TwCenMT.ttf')", `url("${fontTwCenUri}")`)

  .replaceAll('url("./fonts/Namata-Semibold.otf")', `url("${fontNamataUri}")`)
  .replaceAll("url('./fonts/Namata-Semibold.otf')", `url("${fontNamataUri}")`)

  .replaceAll('url("./images/REM-Plantilla.svg")', `url("${bgUri}")`)
  .replaceAll("url('./images/REM-Plantilla.svg')", `url("${bgUri}")`)

