function cleanText(value) {
  return String(value ?? "")
    .replace(/\t/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function normalize(value) {
  return cleanText(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase();
}

function get(row, names) {
  for (const name of names) {
    if (
      row[name] !== undefined &&
      row[name] !== null &&
      String(row[name]).trim() !== ""
    ) {
      return row[name];
    }
  }

  return "";
}

function makeKey(clienteGrupo, plantaCodigo, subplantaCodigo, codigoExcel) {
  return [
    normalize(clienteGrupo),
    normalize(plantaCodigo),
    normalize(subplantaCodigo),
    normalize(codigoExcel)
  ].join("|");
}

function addIfNotEmpty(object, key, value) {
  const text = cleanText(value);

