function cleanText(value) {
  return String(value ?? "").trim();
}

function padRemision(value) {
  return String(value).padStart(4, "0");
}

function safeFileText(value) {
  return cleanText(value)
    .replace(/[<>:"/\\|?*]+/g, "_")
    .replace(/\s+/g, "_");
}

const reserva = $input.first()?.json || {};
const remisiones = $("Normalizar datos CAT").all();
const preparacion = $("Preparar reserva folios PG").first()?.json || {};

if (remisiones.length === 0) {
  throw new Error("No hay remisiones normalizadas para asignar folios.");
}

const reservaId = reserva.reserva_id;
const folioInicial = Number(reserva.folio_inicial);
const folioFinal = Number(reserva.folio_final);
const cantidadReservada = Number(reserva.cantidad);
const serieCodigo = preparacion.serie_codigo;

if (!reservaId) {
  throw new Error("La reserva PostgreSQL no devolvió reserva_id.");
}

if (
  !Number.isInteger(folioInicial) ||
  !Number.isInteger(folioFinal) ||
  !Number.isInteger(cantidadReservada)
) {
  throw new Error("La reserva PostgreSQL devolvió folios o cantidad inválidos.");
}

if (!serieCodigo) {
  throw new Error("No se pudo recuperar serie_codigo.");
}

if (cantidadReservada !== remisiones.length) {
  throw new Error(
    `La reserva contiene ${cantidadReservada} folios, pero existen ${remisiones.length} remisiones.`
  );
}

if (folioFinal - folioInicial + 1 !== cantidadReservada) {
  throw new Error(
    `El rango reservado ${folioInicial}-${folioFinal} no coincide con la cantidad ${cantidadReservada}.`
  );
}

return remisiones.map((item, index) => {
  const data = item.json;
  const folio = folioInicial + index;
  const remisionNo = padRemision(folio);

  const nombreBase =
    data.numero_parte ||
    data.codigo ||
    `ARTICULO_${data.articulo_index || index + 1}`;

  return {
    json: {
      ...data,

      reserva_id: String(reservaId),
      serie_codigo: serieCodigo,
      folio_numero: String(folio),
      remision_no: remisionNo,

      output_file_name: `REM ${remisionNo} ${safeFileText(nombreBase)}.pdf`,
      html_file_name: `REM ${remisionNo} ${safeFileText(nombreBase)}.html`,

      folio_asignado: true
    }
