function fechaSql(fecha) {
  const match = String(fecha ?? "").trim().match(/^(\d{2})\/(\d{2})\/(\d{4})$/);

  if (!match) {
    throw new Error(`Fecha de remisión inválida: "${fecha}".`);
  }

  return `${match[3]}-${match[2]}-${match[1]}`;
}

