function cleanText(value) {
  return String(value ?? "").trim();
}

function normalizeText(value) {
  return cleanText(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .replace(/\s+/g, " ")
    .trim();
}

function isExcelFile(fileName) {
  const name = cleanText(fileName).toLowerCase();

  return (
    name.endsWith(".xlsx") ||
    name.endsWith(".xlsm") ||
    name.endsWith(".xls")
  );
}

function getInputDirs(cfg) {
  if (cfg.usa_anio === true) {
    const baseRutaAnual = cleanText(cfg.base_ruta_anual);

    if (!baseRutaAnual) {
      return [];
    }

    return ANIOS_A_ESCANEAR.map(anio => ({
      input_dir: path.join(baseRutaAnual, String(anio)),
      ruta_base: baseRutaAnual,
      usa_anio: true,
      anio_operacion: String(anio)
    }));
  }

  return [
    {
      input_dir: cfg.ruta,
      ruta_base: cfg.ruta,
      usa_anio: false,
      anio_operacion: ""
    }
  ];
}

function getDateFromFileName(fileName, lastWriteTime) {
  const name = cleanText(fileName);

  // Fecha de 8 dígitos: 20250815
  const matches8 = name.match(/\d{8}/g);

  if (matches8 && matches8.length > 0) {
    const raw = matches8[matches8.length - 1];

    const year = Number(raw.slice(0, 4));
    const month = Number(raw.slice(4, 6));
    const day = Number(raw.slice(6, 8));

    const date = new Date(Date.UTC(year, month - 1, day));

    if (
      !isNaN(date.getTime()) &&
      year >= 2020 &&
      month >= 1 &&
      month <= 12 &&
      day >= 1 &&
      day <= 31
    ) {
      return date;
    }
  }

  // Fecha de 6 dígitos: 260629 = 2026-06-29
  const matches6 = name.match(/\d{6}/g);

  if (matches6 && matches6.length > 0) {
    const raw = matches6[matches6.length - 1];

    const year = 2000 + Number(raw.slice(0, 2));
    const month = Number(raw.slice(2, 4));
    const day = Number(raw.slice(4, 6));

    const date = new Date(Date.UTC(year, month - 1, day));

    if (
      !isNaN(date.getTime()) &&
      year >= 2020 &&
      month >= 1 &&
      month <= 12 &&
      day >= 1 &&
      day <= 31
    ) {
      return date;
    }
  }

  return lastWriteTime;
}

function toIsoDate(date) {
  if (!(date instanceof Date) || isNaN(date.getTime())) return "";

  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  const day = String(date.getUTCDate()).padStart(2, "0");

  return `${year}-${month}-${day}`;
}

function toUnixTimestamp(date) {
  if (!(date instanceof Date) || isNaN(date.getTime())) return 0;
  return Math.floor(date.getTime() / 1000);
}

