      motivo: `Archivo de prueba válido - CAT_TORREON${detectado.subplantaCodigo ? " - " + detectado.subplantaCodigo : ""}`
    };
  }

  // =======================================================
  // NUEVO LAREDO / FINSA 1 / FINSA 3
  // Ejemplos:
  // PROGRAMACIÓN DE ENTREGA CATERPILLAR FINSA 1 PRUEBA.xlsx
  // PROGRAMACIÓN DE ENTREGA CATERPILLAR FINSA 3 PRUEBA.xlsx
  // =======================================================
  if (fileNameNorm.includes("FINSA")) {
    const detectado = detectarFinsa(fileNameNorm);

    return {
      clienteGrupo: "CAT_NUEVO_LAREDO",
      nombrePlanta: "CAT NUEVO LAREDO",
      plantaCodigo: "NUEVO_LAREDO",
      subplantaCodigo: detectado.subplantaCodigo,
      procesar: detectado.procesar,
      motivo: detectado.procesar
        ? `Archivo de prueba válido - CAT_NUEVO_LAREDO - ${detectado.subplantaCodigo}`
        : detectado.motivo
    };
  }

  // =======================================================
  // CATERPILLAR P2
  // Ejemplos:
  // PROGRAMACIÓN DE ENTREGA CAT SC PLANTA 2 PRUEBA.xlsx
  // PROGRAMACIÓN DE ENTREGA CATERPILLAR P2 PRUEBA.xlsx
  // =======================================================
  if (
    fileNameNorm.includes("SC PLANTA 2") ||
    fileNameNorm.includes("SC PL 2") ||
    fileNameNorm.includes("CATERPILLAR P2") ||
    fileNameNorm.includes("CAT P2") ||
    /\bP2\b/.test(fileNameNorm)
  ) {
    return {
      clienteGrupo: "CATERPILLAR_P2",
      nombrePlanta: "CATERPILLAR MEXICO - P2",
      plantaCodigo: "P2",
      subplantaCodigo: "",
      procesar: true,
      motivo: "Archivo de prueba válido - CATERPILLAR_P2 - P2"
    };
  }

  // =======================================================
  // P3 / P4 / P5 / P6
  // Ejemplos:
  // PROGRAMACIÓN DE ENTREGA CAT SC PLANTA 3 PRUEBA.xlsx
  // PROGRAMACIÓN DE ENTREGA CAT CF PLANTA 5 PRUEBA.xlsx
  // PROGRAMACIÓN DE ENTREGA CAT CF PLANTA 6 PRUEBA.xlsx
  // =======================================================
  if (
    fileNameNorm.includes("PLANTA 3") ||
    fileNameNorm.includes("PLANTA 4") ||
    fileNameNorm.includes("PLANTA 5") ||
    fileNameNorm.includes("PLANTA 6") ||
    fileNameNorm.includes("PL 3") ||
    fileNameNorm.includes("PL 4") ||
    fileNameNorm.includes("PL 5") ||
    fileNameNorm.includes("PL 6") ||
    /\bP3\b/.test(fileNameNorm) ||
    /\bP4\b/.test(fileNameNorm) ||
    /\bP5\b/.test(fileNameNorm) ||
    /\bP6\b/.test(fileNameNorm)
  ) {
    const detectado = detectarP3P6(fileNameNorm);

    return {
      clienteGrupo: "CAT_P3_P4_P5_P6",
      nombrePlanta: "CATERPILLAR INDUSTRIAS MEXICO - P3 P4 P5 P6",
      plantaCodigo: detectado.plantaCodigo,
      subplantaCodigo: "",
      procesar: detectado.procesar,
      motivo: detectado.procesar
        ? `Archivo de prueba válido - CAT_P3_P4_P5_P6 - ${detectado.plantaCodigo}`
        : detectado.motivo
    };
  }

  return {
    clienteGrupo: "PRUEBA_LOCAL",
    nombrePlanta: "PRUEBA LOCAL - NO CLASIFICADA",
    plantaCodigo: "NO_CLASIFICADA",
    subplantaCodigo: "",
    procesar: false,
    motivo: "Archivo de prueba detectado, pero no se pudo clasificar cliente/planta desde el nombre"
  };
}

