const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

function cleanText(value) {
  return String(value ?? "").trim();
}

function safeFileText(value) {
  return cleanText(value)
    .replace(/\.[^.]+$/i, "")
    .replace(/[<>:"/\\|?*]+/g, "_")
    .replace(/\s+/g, "_");
}

function pad(value) {
  return String(value).padStart(2, "0");
}

function getTimestamp() {
  const now = new Date();

  return (
    `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}_` +
    `${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`
  );
}

function calcularHashArchivo(filePath) {
  if (!filePath) {
    throw new Error(
      "No se encontró file_path para calcular SHA-256."
    );
  }

  if (!fs.existsSync(filePath)) {
    throw new Error(
      `No se puede calcular SHA-256 porque el archivo no existe: ${filePath}`
    );
  }

  const contenido = fs.readFileSync(filePath);

  return crypto
    .createHash("sha256")
    .update(contenido)
    .digest("hex");
}

