const current = $input.first()?.json || {};

function cleanText(value) {
  return String(value ?? "").trim();
}

function getNodeJson(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch {
    return {};
  }
}

function getFirstExisting(...values) {
  for (const value of values) {
    const text = cleanText(value);

    if (text !== "") {
      return value;
    }
  }

  return "";
}

function getErrorMessage(json) {
  if (json.error?.message) {
    return cleanText(json.error.message);
  }

  if (json.error?.description) {
    return cleanText(json.error.description);
  }

  if (typeof json.error === "string") {
    return cleanText(json.error).slice(0, 3000);
  }

  if (json.error_mensaje) {
    return cleanText(json.error_mensaje);
  }

  if (json.message) {
    return cleanText(json.message);
  }

  if (json.error) {
    try {
      return JSON.stringify(json.error).slice(0, 3000);
    } catch {
      return String(json.error).slice(0, 3000);
    }
  }

  return "Error no especificado por n8n.";
}

function getErrorNode(json) {
  return cleanText(
    json.error?.node?.name ||
    json.error?.node ||
    json.node?.name ||
    json.nodeName ||
    json.nodo_error ||
    ""
  );
}

